fn fibonacci(n: usize) -> Vec<i32> {
    // Since n >= 2 by assumption, initialize the vector with the first two Fibonacci numbers.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    for i in 2..n {
        // Compute F(i) = F(i-1) + F(i-2)
        // The problem guarantees no overflow beyond i32 range.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}